class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        if (nums.size() <= 1) return 0;
        unordered_map<int, int> even, odd;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i % 2 == 0) even[nums[i]]++;
            else odd[nums[i]]++;
        }
        auto getTop2 = [](unordered_map<int, int>& m) -> vector<pair<int, int>> {
            int v1 = 0, c1 = 0, v2 = 0, c2 = 0;
            for (auto& [val, cnt] : m) {
                if (cnt > c1) {
                    v2 = v1; c2 = c1;
                    v1 = val; c1 = cnt;
                } else if (cnt > c2) {
                    v2 = val; c2 = cnt;
                }
            }
            return {{v1, c1}, {v2, c2}};
        };
        auto e = getTop2(even), o = getTop2(odd);
        if (e[0].first != o[0].first) {
            return nums.size() - (e[0].second + o[0].second);
        }
        return nums.size() - max(e[0].second + o[1].second, e[1].second + o[0].second);
    }
};

class Solution {
    public int minimumOperations(int[] nums) {
        if (nums.length <= 1) return 0;
        Map<Integer, Integer> even = new HashMap<>();
        Map<Integer, Integer> odd = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (i % 2 == 0) even.put(nums[i], even.getOrDefault(nums[i], 0) + 1);
            else odd.put(nums[i], odd.getOrDefault(nums[i], 0) + 1);
        }
        int[][] e = getTop2(even);
        int[][] o = getTop2(odd);
        if (e[0][0] != o[0][0]) {
            return nums.length - (e[0][1] + o[0][1]);
        }
        return nums.length - Math.max(e[0][1] + o[1][1], e[1][1] + o[0][1]);
    }
    private int[][] getTop2(Map<Integer, Integer> map) {
        int v1 = 0, c1 = 0, v2 = 0, c2 = 0;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            int v = entry.getKey(), c = entry.getValue();
            if (c > c1) {
                v2 = v1; c2 = c1;
                v1 = v; c1 = c;
            } else if (c > c2) {
                v2 = v; c2 = c;
            }
        }
        return new int[][]{{v1, c1}, {v2, c2}};
    }
}

